  ['ok', /^(ok+|okay|hari+|ela+|හරි|ok dr|hari dr|ela dr|hmm+|mm+|ow|owu|ඔව්|ok ok)$/],
  ['price', /^(ඩිලිවරි ගාස්තුව එක්ක )?(මුළු |මුලු )?(ගාන|ගාණ|මිල) ?(කියද|කීයද|කීයද්ද)$|^(kiyada|kiyd|kiyda|keyada|kiyadha|kiyad|kiyada dr|kiyada mila|mila kiyada|mila|price|price eka|price eka kiyada|price kiyada|price eka one|price please|price plz|how much|how much is it|me priceda|me price eka|gana kiyada|ganan kiyada|ganan kohomada|gana|ganan|ganana|මිල|කීයද|කියද|මිල කීයද|ගාන කීයද|මිල ගනන් කොහොමද|මිල ගණන් කොහොමද|total eka kiyada|delivery ekka kiyada|delivery ekkama kiyada)$/],
  ['delivery', /^(delivery|dilivery|dilewary|delivary|delivery kiyada|delivery charge|delivery charges|delivery gana|delivery gasthu kiyada|dilivery gasthu kiyada|deliver karanawada|delivery thiyenawada|delivery karanawada|ඩිලිවරි|ඩිලිවරි ගාස්තුව කීයද|ඩිලිවරි කරනවද|dawas kiyak yanawada|dawas kiyak yaida|dws kiyak ynwda|kawada enne|kawadda enne|kawada ganna puluwan|kawada wage ganna puluwan|kochchara welawak yanawada|kochchara kalayak yanawada|දවස් කීයක් යනවද|කවදද එන්නේ|කොච්චර කල් යනවද|kochchara kal yanawada)$/],
  ['payment', /^(cash on delivery( da| thiyenawada)?|cod( da| thiyenawada)?|salli kohomada gewanne|gewanne kohomada|payment kohomada|ගෙවන්නේ කොහොමද|සල්ලි ගෙවන්නේ කොහොමද|card payment thiyenawada|online payment)$/],
  ['shop', /^(koheda thiyenne|shop eka koheda|kade koheda|oyala koheda|location eka|oyalage address eka|ඔයාලා කොහෙද|කඩේ කොහෙද|ෂොප් එක කොහෙද|nishpadithaya koheda|koheda hadanne|kadawala thiyenawada|food city wala thiyenawada)$/],
  ['usage', /^(use karanne kohomada|use karana widiha|use karana hati|bonne kohomada|ganna widiha|ganne kohomada|pawichchi karanne kohomada|පාවිච්චි කරන්නේ කොහොමද|බොන්නේ කොහොමද|භාවිතා කරන්නේ කොහොමද|how to use|how to use it|ganna ona widiha)$/],
  ['how_order', /^(ඔඩර් එකක් දාන්නේ කොහොමද|ඕඩර් එකක් දාන්නේ කොහොමද|order ekak danne kohomada|oder ekak danne kohomada|order karanne kohomada|order karanna ona|order ekak danna|order ekak danna ona|how (do i|to|can i) order|i want to order|order|oder|order karanna|order karannam|ඕඩර් කරන්න|ඔඩර් කරන්න|ඕඩර් එකක් දාන්න)( dr| please| plz)?$/],
  ['want', /^(mata(th)? )?(ekak|akak|dekak|thunak|ekak ona|ekak oni|akak ona|ekak one|dekak ona|ekak awanna|akak awanna|ekak ewanna|ekak evanna|dekak evanna|dekak ewanna|ekak ganna|dekak ganna|ona|oni|mata ona|mata oni|ganna ona|ganna kamathi|මට එකක් ඕන|මට ඕන|මටත් එකක් ඕන|මට දෙකක් ඕන|එකක් එවන්න|දෙකක් එවන්න|එකක් ඕන)( puluwada| puluwanda| dr| please| plz)?$/],
  ['call', /^(call (me|karanna|karanna puluwanda|ekak denna|ekak dennako|ekak ganna)|mata call (ekak|karanna)( denna| puluwanda)?|කෝල් එකක් දෙන්න|call එකක් දෙන්න|මට call කරන්න|මට කෝල් කරන්න|කතා කරන්න ඕන)( please| plz| dr)?$/],
  ['greet', /^(hi+|hello+|hey+|helo+|hai+|ayubowan|ආයුබෝවන්|හායි|හලෝ|good (morning|evening|night|afternoon)|gm|ge)( dr| sir| miss)?$/],
];

const bareText = lead ? rest : now;
const norm = normalize(bareText);
const probe = norm || (typed ? 'ok' : '');                 // only emojis (👍 🙏) = "ok"
const compact = probe.replace(/[\s-]/g, '');
const firstContact = !(chat.products_seen || []).length && !(ctx.history || []).some(h => h.r === 'b');
const opener = typed && (PREFILL.test(bareText) || OPENER.test(norm)) && Array.from(norm).length <= 90;

let c = null, source = 'none', rule = '';
const C = (intent, extra = {}) => ({ intent, product_id: 0, name: '', address: '', phone: '', phone2: '', qty: 0, reply: '', needs_human: false, lang: '', memo: '', ...extra });
if (spam) { c = C('spam'); source = 'rule'; rule = 'spam'; }
else if (taps.some(t => String(t).startsWith('FORM'))) {
  // the order form (WhatsApp Flow) was filled in: name, address, phones, quantity, product
  let f = {};
  try { f = JSON.parse(taps.find(t => String(t).startsWith('FORM')).slice(4)); } catch (e) { f = {}; }
  c = C('form', { name: String(f.name || ''), address: String(f.address || ''), phone: localPhone(f.phone) || String(f.phone || ''), phone2: localPhone(f.phone2) || '',
                  qty: Math.min(20, Math.max(1, Number(f.qty) || 1)), product_id: Number(f.pid) || 0 });
  source = 'tap'; rule = 'form';
}
else if (!typed && taps.length) { c = C('tap'); source = 'tap'; }
else if (typed && awaiting.startsWith('field_') && !/[?？]/.test(bareText) && Array.from(norm).length <= 300 && !RULES.slice(4).some(([, re]) => re.test(probe))) {
  const f = awaiting.slice(6);
  const v = f === 'qty' ? qtyOf(bareText) : f === 'phone' ? (phonesIn(bareText)[0] || '') : bareText.replace(/\s+/g, ' ').trim();
  if (v) { c = C('field', { [f === 'qty' ? 'qty' : f]: v, phone2: f === 'phone' ? (phonesIn(bareText)[1] || '') : '' }); source = 'rule'; rule = 'field'; }
} else if (typed && awaiting === 'qty' && qtyOf(bareText)) { c = C('qty', { qty: qtyOf(bareText) }); source = 'rule'; rule = 'qty'; }
if (!c && lead && !/\S/.test(rest)) { c = C('details', { ...lead }); source = 'lead'; }
if (!c && form && (form.name || form.address || form.phone)) {
  c = C('details', { ...(lead || {}), ...Object.fromEntries(Object.entries(form).filter(([, v]) => v)) });
  source = lead ? 'lead' : 'form';
}
if (!c && typed && /^\+?\d{9,12}$/.test(compact) && localPhone(compact)) { c = C('details', { phone: localPhone(compact) }); source = 'rule'; rule = 'phone'; }
if (!c && typed && opener && (firstContact || chat.status === 'new')) { c = C('opener'); source = 'rule'; rule = 'opener'; }
if (!c && typed) {
  for (const [name, re] of RULES) {
    if (!re.test(probe)) continue;
    if ((name === 'yes' || name === 'no') && !['confirm', 'same'].includes(awaiting)) continue;   // "ow" means something only after a question
    rule = name; source = 'rule';
    c = name === 'want' ? C('want_order', { qty: qtyOf(probe) }) : C(name);
    if (lead) Object.assign(c, lead, { intent: 'details' });
    break;
  }
}

// ---------- the brain (one AI call) for everything else ----------
const mode = budget.mode || 'full';
const needAi = !c && typed;
let brain = null;
if (needAi && mode === 'off') c = C('ai_off');
else if (needAi) {
  const model = mode === 'cheap' ? (ai.cheap || 'gpt-5.4-nano') : (ai.brain || 'gpt-5.4-mini');
  const primary = /^gemini/i.test(model) ? 'gemini' : 'openai';
  const fill = s => String(s || '').replace(/\{price\}/g, money((prod || {}).price)).replace(/\{delivery_fee\}/g, money((prod || {}).delivery_fee)).replace(/\{total\}/g, money((prod || {}).total));
  const facts = p => [
    `PRODUCT (id ${p.id}): ${p.name}`,
    `Price Rs. ${money(p.price)} | Delivery Rs. ${money(p.delivery_fee)} to anywhere in Sri Lanka (charged once per order) | Total Rs. ${money(p.total)} | Cash on delivery`,
    `Totals: ${[1, 2, 3, 4, 5].map(n => `${n} = Rs. ${money(Number(p.price) * n + Number(p.delivery_fee))}`).join(', ')}`,
    p.short_description ? `About: ${p.short_description}` : '',
    p.benefits ? `Helps with: ${p.benefits}` : '',
    p.how_to_use ? `How to use: ${p.how_to_use}` : '',
    p.precautions ? `Precautions: ${p.precautions}` : '',
    p.ingredients ? `Ingredients: ${p.ingredients}` : '',
    p.long_description ? `Description (already sent with the photo): ${fill(p.long_description).replace(/[*_]/g, '').replace(/\n+/g, ' / ')}` : '',
    ...(Array.isArray(p.faqs) ? p.faqs.slice(0, 15).map(f => (f && f.q && f.a ? `FAQ: ${f.q} → ${f.a}` : '')) : []),
  ].filter(Boolean).join('\n');
  const productBlock = prod ? facts(prod) : 'PRODUCT: not known yet (they have not said which product they want).';
  const others = matches.filter(p => !prod || p.id !== prod.id).slice(0, 4);
  const o = order;
  const lo = ctx.last_order;
  const orderLine = o
    ? (awaiting === 'confirm'
        ? `waiting for their confirmation: ${o.qty} × ${o.product_name}, ${o.name}, ${o.address}, ${o.phone1}`
        : `being filled in: ${o.qty} × ${o.product_name}; have ${['name', 'address', 'phone1'].filter(k => has(o[k])).map(k => k.replace('1', '')).join(', ') || 'nothing yet'}`)
    : 'none in progress';
  const asked = { details: 'their name, address and phone number', qty: 'how many they want', confirm: 'to confirm the order summary', same: 'if we should use their last order details',
    field_name: 'their new name', field_address: 'their new address', field_phone: 'their new phone number', field_qty: 'the new quantity', product: 'which product they want' }[awaiting] || 'nothing';
  const langName = { si: 'Sinhala script', sg: 'Singlish', en: 'English' }[chat.lang] || 'Sinhala script';
  const label = r => (r === 'c' ? 'Customer: ' : r === 's' ? 'Shop staff: ' : 'Lingo: ');
  const dyn = [
    `SHOP: ${seller.business || 'our shop'}${seller.location ? ', ' + seller.location : ''}. Online shop, island-wide courier delivery in ${seller.delivery_days || '2-3'} days, cash on delivery. Team calls: ${seller.call_hours || 'daytime'}.${seller.phone ? ' Shop phone: ' + seller.phone + '.' : ''}${seller.about ? ' ' + seller.about : ''}`,
    `OTHER PRODUCTS: ${others.length ? others.map(p => `${p.id}: ${p.name} (Rs. ${money(p.price)})`).join(' | ') : 'none mentioned'}`,
    `ORDER: ${orderLine}${lo ? ` | ordered before: ${lo.qty} × ${lo.product_name}` : ''}`,
    `WE ASKED: ${asked}`,
    `CUSTOMER: WhatsApp name "${cut(chat.profile_name || '', 40)}"; writes ${langName}`,
    `MEMO: ${chat.memo || '-'}`,
    'CHAT (oldest first):',
    ...((ctx.history || []).map(h => label(h.r) + cut(h.c, 220))),
    lead ? 'NOTE: their lead form already gave name, address and phone.' : '',
    `NEW MESSAGE: ${cut(bareText || now, 1200)}`,
  ].filter(Boolean).join('\n');
  const props = {
    intent: { type: 'string', enum: ['question', 'details', 'want_order', 'confirm', 'change', 'cancel', 'other_product', 'call_me', 'complaint', 'not_interested', 'chat', 'unclear'] },
    product_id: { type: 'integer' }, name: { type: 'string' }, address: { type: 'string' }, phone: { type: 'string' }, phone2: { type: 'string' },
    qty: { type: 'integer' }, reply: { type: 'string' }, needs_human: { type: 'boolean' }, lang: { type: 'string', enum: ['si', 'sg', 'en'] }, memo: { type: 'string' },
  };
  const required = Object.keys(props);
  const style = has(ctx.style) && typeof ctx.style === 'string' ? `\n\nSHOP STYLE NOTES: ${cut(ctx.style, 600)}` : '';
  const openai_req = {
    model: primary === 'openai' ? model : (ai.cheap || 'gpt-5.4-nano'),
    messages: [{ role: 'system', content: PERSONA + style }, { role: 'system', content: productBlock }, { role: 'user', content: dyn }],
    response_format: { type: 'json_schema', json_schema: { name: 'lingo_turn', strict: true, schema: { type: 'object', additionalProperties: false, properties: props, required } } },
    max_completion_tokens: 900,
    prompt_cache_key: 'lingo-feeder-p' + (prod ? prod.id : 0),
  };
  if (/^gpt-5/.test(openai_req.model) && has(ai.openai_reasoning)) openai_req.reasoning_effort = String(ai.openai_reasoning);
  if (ai.openai_cache_24h === true) openai_req.prompt_cache_retention = '24h';
  const gemini_model = primary === 'gemini' ? model : (ai.fallback || 'gemini-3.5-flash-lite');
  const gemini_req = {
    systemInstruction: { parts: [{ text: PERSONA + style + '\n\n' + productBlock }] },
    contents: [{ role: 'user', parts: [{ text: dyn }] }],
    generationConfig: { maxOutputTokens: 1200, responseMimeType: 'application/json', responseJsonSchema: { type: 'object', properties: props, required },
                        thinkingConfig: { thinkingLevel: ai.gemini_thinking || 'minimal' } },
  };
  brain = { primary, openai_model: openai_req.model, gemini_model, openai_req, gemini_req, started: Date.now(), chars: PERSONA.length + productBlock.length + dyn.length };
}

const langText = (lead ? rest : now).replace(PREFILL, ' ');
return [{ json: {
  now, typed, taps, lead, form, spam, opener, rule, source, first_contact: firstContact,
  c, need_ai: !!brain, brain, mode,
  lang_guess: typed && !opener ? guessLang(langText, chat.lang || 'si') : (chat.lang || 'si'),
} }];

// Lingo's whole reply, decided in code (one consistent flow for every chat):
//   first message from an ad → 1) product photo + full description  2) "Good evening Nimal 😊 I'm Lingo…"
//     with the total and the details form, and buttons 🛒 Order · 📖 How to use · 📞 Call me
//   order: quantity list → details (or "same details as last time?") → only what's missing → summary with
//     ✅ Confirm · ✏️ Change · ❌ Cancel → thank-you with their name + how to use the product
//   questions: fixed texts (price, delivery, payment, shop, how to use) or the AI's answer after the
//     OUTPUT GUARD (no banned claims, no numbers that aren't in the facts, right script, short)
//   another product mentioned → Lingo switches to it (photo + details) and can take a second order
//   every turn also sets the chat's status (only clicked · asking · giving details · ordered · cancelled ·
//   not interested · spam) and "call them" when a person is needed.
// ---- Lingo Feeder shared helpers (copied into each Code node that says "@include lib.js") ----
const cut = (s, n) => { s = String(s == null ? '' : s); return Array.from(s).length > n ? Array.from(s).slice(0, n).join('') + '…' : s; };
const clip = (s, n) => Array.from(String(s == null ? '' : s)).slice(0, n).join('');
const has = v => v !== undefined && v !== null && String(v).trim() !== '';
const money = n => Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });

/** Lower case, no emojis / punctuation, single spaces: what the quick rules match against. */
const normalize = s => String(s || '').normalize('NFC').toLowerCase()
  .replace(/\p{Extended_Pictographic}/gu, ' ').replace(/[\u{1F3FB}-\u{1F3FF}\u{FE0F}\u{20E3}‍]/gu, '')
  .replace(/[\p{P}\p{S}]/gu, ' ').replace(/\s+/g, ' ').trim();

/** A Sri Lankan mobile number → 0XXXXXXXXX (else ''). */
const localPhone = v => {
  const d = String(v || '').replace(/\D/g, '');
  if (/^94\d{9}$/.test(d)) return '0' + d.slice(2);
  if (/^0\d{9}$/.test(d)) return d;
  if (/^[1-9]\d{8}$/.test(d)) return '0' + d;
  return '';
};

/** A WhatsApp profile name that looks like a first name ("Nimal", "නිමල්"), else ''. */
const NOT_NAMES = new Set(['shop', 'store', 'stores', 'official', 'online', 'mobile', 'phone', 'user', 'whatsapp', 'business', 'enterprises', 'lk', 'the', 'mr', 'mrs', 'miss', 'dr', 'hi', 'hello']);
const firstName = n => {
  const w = String(n || '').replace(/[^A-Za-z඀-෿ ]+/g, ' ').trim().split(/\s+/)[0] || '';
  if (/^[A-Za-z]{2,20}$/.test(w) && !NOT_NAMES.has(w.toLowerCase())) return w[0].toUpperCase() + w.slice(1).toLowerCase();
  if (/^[඀-෿]{2,20}$/.test(w)) return w;
  return '';
};

/** Which style the customer writes in: si (Sinhala script) · sg (Singlish) · en, else keep prev. */
const SINGLISH = /\b(kiyada|kiyd|kiyda|keyada|puluwan\w*|pluwan\w*|ona|oni|one|onee|mata|matath|eka|ekak|akak|dekak|dr|ganna|gnna|danna|denna|karanna|thiyenawa\w*|thiyanawa\w*|nadda|neda|nedda|nathi|na|naa|ow|owu|hari|mokak\w*|kohom\w*|koheda|kawad\w*|wenawa\w*|gena|ewanna|awanna|evanna|bonna|beheth|gedara\w*|salli|ganan|gana|mila|dawas|kiyak|yanawa\w*|enawa\w*|ammala|lamai\w*|ayata|walata|nam|thama|tama|aiyo|ayyo|aney|ane|ela|harida|denne|ganne|wage|witharada|witharai|puluwanda|onada)\b/;
const ENGLISH = /\b(how|what|when|where|which|is|are|can|could|do|does|please|want|need|send|my|the|your|price|much|deliver|order|thank|thanks|hello|available)\b/;
const guessLang = (text, prev) => {
  const s = String(text || '');
  const si = (s.match(/[඀-෿]/g) || []).length;
  const lat = (s.match(/[A-Za-z]/g) || []).length;
  if (si >= 2 && si >= lat * 0.5) return 'si';
  if (lat < 3) return prev;
  const w = s.toLowerCase();
  if (SINGLISH.test(w)) return 'sg';
  if (ENGLISH.test(w) && w.split(/\s+/).length >= 2) return 'en';
  return prev;
};

/** Good morning / afternoon / evening / night key, Sri Lanka time. */
const greetKey = (d = new Date()) => {
  const h = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Colombo', hour: 'numeric', hour12: false }).format(d)) % 24;
  return h >= 4 && h < 12 ? 'greet_morning' : h >= 12 && h < 16 ? 'greet_afternoon' : h >= 16 && h < 20 ? 'greet_evening' : 'greet_night';
};

/** One text in the customer's style (Singlish → Sinhala text if no Singlish one), placeholders filled. */
const makeText = (texts, lang) => (key, vals = {}) => {
  const t = texts[key] || {};
  const raw = String(t[lang] || (lang === 'sg' ? t.si : '') || t.si || t.en || '');
  return raw.replace(/\{(\w+)\}/g, (x, k) => (k in vals ? String(vals[k] == null ? '' : vals[k]) : x))
    .replace(/[ \t]{2,}/g, ' ').replace(/ +([!?.,😊🙏👇])/g, ' $1').replace(/^ +| +$/gm, '').replace(/ ([!?.,])/g, '$1')
    .replace(/\n{3,}/g, '\n\n').trim();
};

/** The Click-to-WhatsApp pre-filled text ("Hello! Can I get more info on this?") and other openers. */
const PREFILL = /(can i get more info|more info(rmation)? (on|about) this|i('m| am) interested in this|tell me more about this|send me more info|වැඩි විස්තර ලබා ගත හැකිද|මට මේ ගැන (වැඩි )?විස්තර|මේ ගැන තව විස්තර)/i;
const OPENER = /^(hi+|hello+|hey+|helo+|hai+|ayubowan|ආයුබෝවන්|හායි|හලෝ|good (morning|evening|night|afternoon)|gm|ge|details|details please|more details|more info|info|wisthara|wistara|wisthara denna|විස්තර|විස්තර දෙන්න|විස්තර ඕන|price list)( dr| sir| miss| please| plz)?$|^.{0,60}(ගෙන්න ගන්න|ගෙන්නගන්න|ගෙන්වා ගන්න|genna ganna|gennaganna|genna ganne) ?(පුලුවන්ද|පුළුවන්ද|පුලුවන් ද|පුළුවන් ද|puluwanda|puluwan da|pluwanda)$/;
const m = $('Message').first().json;
const ctx = $('Claim Batch').first().json;
const u = $('Understand').first().json;
const chat = ctx.chat || {};
const seller = ctx.seller || m.seller || {};
const texts = ctx.texts || {};
const banned = (Array.isArray(ctx.banned) ? ctx.banned : []).map(x => String(x).toLowerCase()).filter(Boolean);

// ---------- the AI's reading (if it was asked) ----------
const INTENTS = ['question', 'details', 'want_order', 'confirm', 'change', 'cancel', 'other_product', 'call_me', 'complaint', 'not_interested', 'chat', 'unclear'];
const parse = s => { try { return JSON.parse(String(s || '').replace(/```(json)?/g, '').trim()); } catch (e) { return null; } };
const gtext = g => ((((g || {}).candidates || [])[0] || {}).content || { parts: [] }).parts.filter(x => !x.thought).map(x => x.text || '').join('');
let c = u.c, aiFrom = '', aiError = '';
if (u.need_ai) {
  const o = $('OpenAI: Brain').isExecuted ? ($('OpenAI: Brain').first().json || {}) : null;
  const g = $('Gemini: Brain').isExecuted ? ($('Gemini: Brain').first().json || {}) : null;
  let got = null;
  if (o && !o.error) { got = parse((((o.choices || [])[0] || {}).message || {}).content); if (got) aiFrom = 'openai'; }
  if (!got && g && !g.error) { got = parse(gtext(g)); if (got) aiFrom = 'gemini'; }
  if (got && INTENTS.includes(got.intent)) c = got;
  else { c = { intent: 'ai_failed' }; aiError = String(((o || {}).error || {}).message || ((g || {}).error || {}).message || 'no answer').slice(0, 200); }
}
c = c || { intent: 'none' };
const intent = c.intent;

// ---------- language: the AI's reading > the words they typed > the chat so far ----------
let lang = ['si', 'sg', 'en'].includes(u.lang_guess) ? u.lang_guess : (chat.lang || 'si');
if (aiFrom && ['si', 'sg', 'en'].includes(c.lang)) lang = c.lang;
const T = makeText(texts, lang);

// ---------- the product in focus: a tapped one → a quoted one → the AI's pick → the only one named ----------
const byId = {};
for (const p of [ctx.product, ctx.quoted, ...(ctx.matches || [])]) if (p && p.enabled !== false) byId[Number(p.id)] = p;
let prod = ctx.product && ctx.product.enabled !== false ? ctx.product : null;
let pid = prod ? Number(prod.id) : 0, switched = false, want = 0;
for (const t of u.taps) if (/^P_\d+$/.test(t)) want = Number(t.slice(2));
if (!want && intent === 'form' && Number(c.product_id) && byId[Number(c.product_id)]) want = Number(c.product_id);
if (!want && ctx.quoted && Number(ctx.quoted.id) !== pid) want = Number(ctx.quoted.id);
if (!want && aiFrom && Number(c.product_id) && byId[Number(c.product_id)]) want = Number(c.product_id);
if (!want && !pid) {
  const ms = (ctx.matches || []).filter(p => p.enabled !== false);
  if (ms.length === 1 || (ms.length > 1 && ms[0].score >= 8 && ms[0].score >= 2 * ms[1].score)) want = Number(ms[0].id);
}
if (want && byId[want] && want !== pid) { pid = want; prod = byId[want]; switched = !!ctx.product; }
const seen = (chat.products_seen || []).map(Number);

// ---------- values for the texts ----------
const waPhone = m.test ? '0700000000' : localPhone(m.phone);
let draft = ctx.order ? { ...ctx.order } : null;
const saved = chat.details || {};
const fname = firstName((draft && draft.name) || saved.name || '') || firstName(chat.profile_name);
const totalFor = (p, q) => money(Number(p.price) * q + Number(p.delivery_fee));
const V = (extra = {}) => ({
  greet: T(greetKey()), name: fname, business: seller.business || '', location: seller.location ? ', ' + seller.location : '',
  delivery_days: seller.delivery_days || '2-3', call_hours: seller.call_hours || '',
  product: prod ? prod.name : '', price: prod ? money(prod.price) : '', delivery_fee: prod ? money(prod.delivery_fee) : '', total: prod ? money(prod.total) : '',
  ...extra,
});
const OV = o => {
  const p = byId[Number(o.product_id)] || prod || {};
  return V({ product: p.name || o.product_name || '', qty: o.qty || 1, o_name: o.name || '', o_first: firstName(o.name) || o.name || fname,
             o_address: o.address || '', o_phones: [o.phone1, o.phone2].filter(Boolean).join(' / '),
             total: p.price ? totalFor(p, o.qty || 1) : money(o.total), delivery_fee: money(p.delivery_fee || o.delivery_fee) });
};
const B = (id, key) => ({ id, title: clip(T(key), 20) });
const title = s => clip(/^[a-z]/.test(s) ? s[0].toUpperCase() + s.slice(1) : s, 24);

// ---------- what we send ----------
const blocks = [], log = [], seenAdd = [], answers = [];
let awaitingOut = null, orderingNow = false, event = '', needsCall = false, callReason = '', pause = false, unsure = false, notInterested = false, detailsOut = null;
let route = u.need_ai ? 'ai' : (u.source === 'tap' ? 'tap' : 'code');
let stepAdded = false;
const step = b => { blocks.push(b); stepAdded = true; };
const answer = (text, note) => { if (text) { answers.push(text); log.push(note); } };

const intro = p => {
  const fillP = s => String(s || '').replace(/\{price\}/g, money(p.price)).replace(/\{delivery_fee\}/g, money(p.delivery_fee)).replace(/\{total\}/g, money(p.total));
  const cap = clip(fillP(p.long_description || p.short_description || p.name), 1024);
  blocks.push(p.picture_url ? { kind: 'image', image: p.picture_url, caption: cap, pid: p.id } : { kind: 'text', text: cap, pid: p.id, sep: true });
  seenAdd.push(Number(p.id));
  log.push(`[sent ${p.name} photo + details]`);
};

// ---------- the order ----------
const fresh = () => ({ id: null, product_id: pid, qty: 1, name: '', address: '', phone1: '', phone2: '', status: 'draft' });
const ensureDraft = () => { if (!draft || draft.status !== 'draft') draft = fresh(); if (pid && draft.product_id !== pid) draft.product_id = pid; return draft; };
const missingOf = o => ['name', 'address', 'phone'].filter(k => !has(k === 'phone' ? o.phone1 : o[k]));
const anyDetail = o => !!o && (has(o.name) || has(o.address));
const savedFull = has(saved.name) && has(saved.address) && has(saved.phone);
const cleanName = s => String(s || '').replace(/\s+/g, ' ').replace(/^[\s:,-]+|[\s:,.-]+$/g, '').trim();
function applyDetails(d, opts = {}) {
  ensureDraft();
  if (has(d.name)) draft.name = clip(cleanName(d.name), 80);
  if (has(d.address)) draft.address = clip(cleanName(d.address), 300);
  let p1 = String(d.phone || '').trim();
  if (/^same$/i.test(p1)) p1 = waPhone;
  p1 = localPhone(p1) || (p1.replace(/\D/g, '').length >= 9 ? clip(p1.replace(/[^\d+]/g, ''), 20) : '');
  const p2 = localPhone(d.phone2);
  if (p1) { if (opts.replace || !draft.phone1 || draft.phone1 === waPhone) draft.phone1 = p1; else if (p1 !== draft.phone1) draft.phone2 = p1; }
  if (p2 && p2 !== draft.phone1) draft.phone2 = p2;
  if (Number(d.qty) > 0) draft.qty = Math.min(20, Math.round(Number(d.qty)));
  if (!has(draft.phone1) && waPhone) draft.phone1 = waPhone;         // their WhatsApp number, shown in the summary
  orderingNow = true;
}
const askQty = () => {
  step({ kind: 'list', text: T('ask_qty', V()), button: T('btn_qty'), section: T('f_qty'),
    rows: [1, 2, 3, 4, 5].map(n => ({ id: 'QTY_' + n, title: title(T('qty_row', { qty: n })), description: clip(T('qty_desc', { total: totalFor(prod, n) }), 72) })) });
  awaitingOut = 'qty'; orderingNow = true; log.push('[asked how many]');
};
const flowId = seller.flow_id || null;
const flowCfg = seller.flow || {};
/** The order form (WhatsApp Flow): prefilled with what we know, quantities with their totals. */
const askForm = () => {
  const d = draft || {};
  step({ kind: 'flow', text: T('ask_form', V()), cta: T('btn_form'), flow_id: flowId, version: String(flowCfg.message_version || '3'),
    token: `lf-${pid}-${Date.now().toString(36)}`,
    data: {
      product: clip(prod.name, 80), pid: String(pid),
      price_line: clip(`Rs. ${money(prod.price)} + delivery Rs. ${money(prod.delivery_fee)} · Cash on delivery`, 120),
      name: clip(d.name || saved.name || firstName(chat.profile_name) || '', 80), phone: d.phone1 || saved.phone || waPhone || '',
      qty: String(d.qty || 1),
      qty_options: [1, 2, 3, 4, 5].map(n => ({ id: String(n), title: clip(`${n} · Rs. ${totalFor(prod, n)}`, 30) })),
    } });
  awaitingOut = 'details'; orderingNow = true; log.push('[sent the order form]');
};
const askDetails = () => {
  if (flowId && prod) return askForm();
  step({ kind: 'text', text: T('ask_details', V()) }); awaitingOut = 'details'; log.push('[asked name, address, phone]');
};
const askMissing = () => {
  const words = missingOf(draft).map(k => T('f_' + k));
  const list = words.length < 2 ? words.join('') : words.slice(0, -1).join(', ') + T('and') + words[words.length - 1];
  step({ kind: 'text', text: T('ask_missing', V({ missing: list })) }); awaitingOut = 'details'; log.push(`[asked for: ${missingOf(draft).join(', ')}]`);
};
const summary = () => {
  step({ kind: 'buttons', text: T('summary', OV(draft)), buttons: [B('CONFIRM', 'btn_confirm'), B('CHANGE', 'btn_change'), B('CANCEL', 'btn_cancel')] });
  awaitingOut = 'confirm'; orderingNow = true; log.push('[sent order summary, asked to confirm]');
};
const nextStep = () => {
  const miss = missingOf(draft);
  if (!miss.length) summary();
  else if (!anyDetail(draft) && miss.length >= 2) askDetails();
  else askMissing();
};
const sameDetails = () => {
  step({ kind: 'buttons', text: T('same_details', V({ o_name: saved.name, o_address: saved.address, o_phones: [saved.phone, saved.phone2].filter(Boolean).join(' / ') })),
    buttons: [B('SAME', 'btn_same'), B('NEW', 'btn_new')] });
  awaitingOut = 'same'; orderingNow = true; log.push('[asked: same details as last time?]');
};
const startOrder = (qty, viaTap) => {
  ensureDraft();
  if (qty) draft.qty = qty;
  if (!missingOf(draft).length && anyDetail(draft)) return summary();
  if (anyDetail(draft)) return nextStep();
  if (savedFull) return sameDetails();
  if (!qty && viaTap && !flowId) return askQty();
  return askDetails();
};
const confirmOrder = () => {
  draft.status = 'confirmed'; event = 'confirmed'; orderingNow = false;
  const p = byId[Number(draft.product_id)] || prod;
  step({ kind: 'text', text: T('confirmed', OV(draft)), sep: true });
  if (p && has(p.how_to_use)) {
    step({ kind: 'text', text: T('how_to_use', V({ product: p.name, how_to_use: p.how_to_use, precautions: has(p.precautions) ? '\n\n⚠️ ' + p.precautions : '' })), sep: true });
  }
  detailsOut = { name: draft.name, address: draft.address, phone: draft.phone1, phone2: draft.phone2 || '' };
  awaitingOut = null; log.push('[order confirmed; sent thank-you and how to use]');
};
const changePick = () => {
  step({ kind: 'list', text: T('change_pick', V()), button: T('btn_pick'), section: T('btn_change'),
    rows: [['CH_NAME', '👤 ', 'f_name'], ['CH_ADDRESS', '🏠 ', 'f_address'], ['CH_PHONE', '📞 ', 'f_phone'], ['CH_QTY', '🔢 ', 'f_qty']]
      .map(([id, e, k]) => ({ id, title: clip(e + title(T(k)), 24), description: '' })) });
  awaitingOut = null; orderingNow = true; log.push('[asked what to change]');
};
const cancelOrder = () => {
  const lo = ctx.last_order;
  if (draft && draft.status === 'draft' && (anyDetail(draft) || awaitingOut || chat.awaiting)) {
    draft.status = 'cancelled'; event = 'cancelled';
  } else if (lo && lo.status === 'confirmed' && !lo.exported_at && Date.now() - new Date(lo.confirmed_at || lo.updated_at).getTime() < 24 * 3600e3) {
    draft = { ...lo, status: 'cancelled' }; event = 'cancelled';
  } else if (lo && lo.status === 'confirmed') {
    needsCall = true; callReason = `Wants to cancel order #${lo.id} (already sent to the courier file)`;
    step({ kind: 'text', text: T('will_check', V()) }); log.push('[wants to cancel a sent order: the shop will call]');
    return;
  }
  step({ kind: 'text', text: T('cancelled', V()) }); awaitingOut = null; log.push('[order cancelled]');
};

// ---------- the AI's answer, checked before it is sent ----------
function guard(r) {
  const low = r.toLowerCase();
  const b = banned.find(x => low.includes(x));
  if (b) return `banned claim "${b}"`;
  const nums = s => (String(s).match(/\d+(?:[.,]\d+)*/g) || []).map(x => x.replace(/,/g, '').replace(/\.0+$/, '').replace(/^0+(?=\d)/, ''));
  const p = prod || {};
  const factText = [p.price, p.delivery_fee, p.total, [1, 2, 3, 4, 5].map(n => Number(p.price) * n + Number(p.delivery_fee)).join(' '), p.how_to_use, p.precautions,
    p.ingredients, p.benefits, p.short_description, p.long_description, JSON.stringify(p.faqs || []), seller.delivery_days, seller.call_hours, seller.phone,
    seller.about, ...(ctx.matches || []).map(x => `${x.price} ${x.total}`), '1 2 3 24 7 100'].join(' ');
  const allowed = new Set(nums(factText));
  const strange = nums(r).filter(n => !allowed.has(n));
  if (strange.length) return `number not in the facts (${strange.slice(0, 3).join(', ')})`;
  if (Array.from(r).length > 600) return 'answer too long';
  const si = (r.match(/[඀-෿]/g) || []).length, lat = (r.match(/[A-Za-z]/g) || []).length;
  if (lang === 'si' && si < lat * 0.6) return 'not in Sinhala';
  if ((lang === 'sg' || lang === 'en') && si > 3) return 'Sinhala letters for a Singlish/English chat';
  return '';
}
const aiReply = () => {
  const r = String(c.reply || '').trim();
  if (!r) return '';
  const why = guard(r);
  if (why) { needsCall = true; callReason = `Lingo's answer was held back (${why}): "${cut(u.now, 80)}"`; log.push(`[AI answer blocked: ${why}]`); return T('will_check', V()); }
  return r;
};

// =====================================================================
// The flow
// =====================================================================
const tap = u.taps.find(t => !/^P_\d+$/.test(t)) || '';
const firstContact = u.first_contact;
const status0 = chat.status || 'new';
let saidSomething = u.taps.length > 0 || (u.typed && !(u.opener && firstContact));

if (intent === 'spam') {
  log.push('[spam link: no reply]');
} else if (!prod) {
  // Which product? (unknown ad, or a message that names none)
  const ms = (ctx.matches || []).filter(p => p.enabled !== false).slice(0, 10);
  if (u.form || u.lead || intent === 'details') {
    const d = { ...(u.lead || {}), ...(u.form || {}), ...(aiFrom ? c : {}) };
    detailsOut = { name: cleanName(d.name || saved.name || ''), address: cleanName(d.address || saved.address || ''), phone: localPhone(d.phone) || saved.phone || waPhone, phone2: localPhone(d.phone2) || '' };
  }
  const r = aiFrom ? aiReply() : '';
  if (ms.length > 1) {
    step({ kind: 'list', text: [firstContact ? T('hello', V()) : '', r, T('pick_product', V())].filter(Boolean).join('\n\n'), button: T('btn_products'), section: 'Products',
      rows: ms.map(p => ({ id: 'P_' + p.id, title: clip(p.name, 24), description: clip(`Rs. ${money(p.price)} · ${p.short_description || ''}`, 72) })) });
    log.push('[asked which product (list)]');
  } else if (firstContact || !r) {
    step({ kind: 'text', text: [r, T('ask_product', V())].filter(Boolean).join('\n\n') }); log.push('[asked which product]');
  } else {
    answer(r, `[answered: ${cut(r, 120)}]`);
  }
  awaitingOut = 'product';
  if (intent === 'call_me') { needsCall = true; callReason = 'Asked for a call'; }
  if (intent === 'complaint') { needsCall = true; callReason = `Complaint: "${cut(u.now, 100)}"`; pause = true; }
} else {
  const needIntro = !seen.includes(pid) && !['CONFIRM', 'CANCEL', 'CHANGE', 'SAME', 'NEW'].includes(tap) && !/^(QTY|CH)_|^FORM/.test(tap);
  if (needIntro) intro(prod);
  if (switched && draft && draft.status === 'draft') draft.product_id = pid;

  const qtyTap = /^QTY_(\d+)$/.exec(tap);
  const chTap = /^CH_(NAME|ADDRESS|PHONE|QTY)$/.exec(tap);
  const det = ['details', 'field', 'qty'].includes(intent) || (aiFrom && (has(c.name) || has(c.address) || has(c.phone)));

  if (intent === 'form') {
    applyDetails({ name: c.name, address: c.address, phone: c.phone, phone2: c.phone2, qty: c.qty }, { replace: true });
    if (c.phone2 === '') draft.phone2 = '';
    nextStep();
  } else if (qtyTap || intent === 'qty' || (intent === 'field' && chat.awaiting === 'field_qty')) {
    ensureDraft(); draft.qty = qtyTap ? Number(qtyTap[1]) : Number(c.qty) || 1; orderingNow = true;
    if (anyDetail(draft)) nextStep(); else if (savedFull) sameDetails(); else askDetails();
  } else if (tap === 'ORDER' || intent === 'want_order' || rule('how_order')) {
    if (aiFrom && det) { applyDetails(c); nextStep(); } else startOrder(Number(c.qty) || 0, tap === 'ORDER');
  } else if (tap === 'SAME' || (intent === 'yes' && chat.awaiting === 'same')) {
    applyDetails({ name: saved.name, address: saved.address, phone: saved.phone, phone2: saved.phone2 }, { replace: true }); nextStep();
  } else if (tap === 'NEW' || (intent === 'no' && chat.awaiting === 'same')) {
    ensureDraft(); draft.name = ''; draft.address = ''; draft.phone1 = ''; draft.phone2 = ''; orderingNow = true; askDetails();
  } else if (tap === 'CONFIRM' || (intent === 'yes' && chat.awaiting === 'confirm') || (intent === 'confirm' && chat.awaiting === 'confirm')) {
    if (draft && draft.status === 'draft' && !missingOf(draft).length) confirmOrder();
    else if (!draft && ctx.last_order) { step({ kind: 'text', text: T('thanks', V()) }); log.push('[already confirmed]'); }
    else { ensureDraft(); nextStep(); }
  } else if (tap === 'CHANGE' || (intent === 'no' && chat.awaiting === 'confirm') || (intent === 'change' && !(has(c.name) || has(c.address) || has(c.phone) || Number(c.qty) > 0))) {
    if (draft && draft.status === 'draft') changePick(); else { ensureDraft(); nextStep(); }
  } else if (chTap) {
    ensureDraft(); orderingNow = true;
    if (chTap[1] === 'QTY') askQty();
    else { const f = chTap[1].toLowerCase(); step({ kind: 'text', text: T('change_ask', V({ field: T('f_' + f) })) }); awaitingOut = 'field_' + f; log.push(`[asked for the new ${f}]`); }
  } else if (tap === 'CANCEL' || intent === 'cancel') {
    cancelOrder();
  } else if (intent === 'field') {
    const f = String(chat.awaiting).slice(6);
    applyDetails({ [f]: c[f], phone2: c.phone2 }, { replace: true });
    nextStep();
  } else if (det) {
    applyDetails(aiFrom ? c : c, { replace: intent === 'change' });
    const r = aiFrom ? aiReply() : '';
    if (r) answer(r, `[answered: ${cut(r, 120)}]`);
    if (firstContact && (u.lead || u.form)) blocks.push({ kind: 'note', text: T('got_details', V()) });
    nextStep();
  } else if (tap === 'USAGE' || rule('usage')) {
    answer(has(prod.how_to_use) ? T('how_to_use', V({ how_to_use: prod.how_to_use, precautions: has(prod.precautions) ? '\n\n⚠️ ' + prod.precautions : '' })) : T('will_check', V()), '[sent how to use]');
    if (!has(prod.how_to_use)) { needsCall = true; callReason = 'Asked how to use it (no instructions saved for this product)'; }
  } else if (tap === 'PRICE' || rule('price')) {
    if (!needIntro) answer(T('price', V()), '[sent price]');
  } else if (rule('delivery')) {
    answer(T('delivery', V()), '[sent delivery details]');
  } else if (rule('payment')) {
    answer(T('payment', V()), '[sent payment details]');
  } else if (rule('shop')) {
    answer(T('shop', V()), '[sent shop details]');
  } else if (tap === 'CALL' || rule('call') || intent === 'call_me') {
    needsCall = true; callReason = 'Asked for a call';
    step({ kind: 'text', text: T('call_ok', V()) }); log.push('[the shop will call]');
  } else if (intent === 'complaint') {
    needsCall = true; pause = true; callReason = `Complaint: "${cut(u.now, 100)}"`;
    step({ kind: 'text', text: T('complaint', V()) }); log.push('[complaint: the shop will call]');
  } else if (intent === 'not_interested' || (intent === 'no' && !chat.awaiting)) {
    notInterested = true;
    const r = aiFrom ? aiReply() : '';
    step({ kind: 'text', text: r || T('not_interested', V()) }); log.push('[not interested]');
  } else if (intent === 'opener' || (intent === 'greet' && firstContact)) {
    if (!firstContact && !needIntro) okReply();                 // the welcome is added below on the first message
  } else if (['thanks', 'ok', 'greet'].includes(intent) || (aiFrom && intent === 'chat' && !String(c.reply || '').trim())) {
    const ordered = status0 === 'ordered' || (ctx.last_order && !draft);
    if (chat.awaiting === 'details' && intent === 'ok') log.push('[ok: waiting for their details]');
    else if (ordered) { answer(T('thanks', V()), '[said thanks]'); }
    else if (!needIntro) okReply();
  } else if (intent === 'ai_failed' || intent === 'ai_off') {
    needsCall = true; callReason = intent === 'ai_off' ? `AI allowance used up; asked: "${cut(u.now, 80)}"` : `Lingo couldn't answer (AI error): "${cut(u.now, 80)}"`;
    step({ kind: 'text', text: T('will_check', V()) }); log.push('[will check: the shop will call]');
  } else if (intent === 'unclear' || (aiFrom && intent !== 'other_product' && !String(c.reply || '').trim())) {
    unsure = true;
    if (Number(chat.unsure || 0) >= 1) {
      needsCall = true; callReason = `Lingo didn't understand twice: "${cut(u.now, 80)}"`;
      step({ kind: 'text', text: T('will_check', V()) }); log.push('[unclear twice: the shop will call]');
    } else {
      step({ kind: 'buttons', text: T('unclear', V()), buttons: [B('ORDER', 'btn_order'), B('USAGE', 'btn_usage'), B('CALL', 'btn_call')] }); log.push('[asked what they mean]');
    }
  } else if (intent === 'other_product' && !switched) {
    const ms = (ctx.matches || []).filter(p => p.enabled !== false && Number(p.id) !== pid).slice(0, 10);
    const r = aiReply();
    if (ms.length > 1) {
      step({ kind: 'list', text: [r, T('pick_product', V())].filter(Boolean).join('\n\n'), button: T('btn_products'), section: 'Products',
        rows: ms.map(p => ({ id: 'P_' + p.id, title: clip(p.name, 24), description: clip(`Rs. ${money(p.price)} · ${p.short_description || ''}`, 72) })) });
      log.push('[asked which product (list)]');
    } else answer(r || T('will_check', V()), `[answered: ${cut(r, 120)}]`);
  } else if (aiFrom) {
    const r = aiReply();
    answer(r, `[answered: ${cut(r, 120)}]`);
    if (c.needs_human === true && !needsCall) { needsCall = true; callReason = `Lingo wasn't sure: "${cut(u.now, 80)}"`; }
  }

  // First message of the chat: the greeting with the total and the details form (+ any answer).
  if (firstContact && !stepAdded) {
    step({ kind: 'buttons', text: [T('hello', V()), ...answers, answers.length ? '' : T('total_line', V()), T('details_form', V())].filter(Boolean).join('\n\n'),
      buttons: [B('ORDER', 'btn_order'), B('USAGE', 'btn_usage'), B('CALL', 'btn_call')] });
    answers.length = 0;
    awaitingOut = awaitingOut || 'details';
    log.push('[greeted them, asked for name, address, phone]');
  } else if (firstContact && stepAdded) {
    const i = blocks.findIndex(b => b.kind !== 'image' && b.kind !== 'note' && !b.pid);
    const note = blocks.find(b => b.kind === 'note');
    if (i >= 0) blocks[i].text = [T('hello', V()), note ? note.text : '', ...answers, blocks[i].text].filter(Boolean).join('\n\n');
    answers.length = 0;
  } else if (needIntro && !stepAdded && !answers.length) {
    if (!ctx.last_order && has(saved.name) && has(saved.address)) {
      // details they gave before we knew the product
      applyDetails({ name: saved.name, address: saved.address, phone: saved.phone, phone2: saved.phone2 }, { replace: true });
      nextStep();
    } else if (ctx.last_order || switched) {
      step({ kind: 'buttons', text: T('next_product', V()), buttons: [B('ORDER', 'btn_order'), B('USAGE', 'btn_usage')] });
      log.push('[offered to order this product]');
    } else {
      step({ kind: 'buttons', text: [T('total_line', V()), T('details_form', V())].join('\n\n'), buttons: [B('ORDER', 'btn_order'), B('USAGE', 'btn_usage'), B('CALL', 'btn_call')] });
      awaitingOut = 'details'; log.push('[asked for name, address, phone]');
    }
  }
}
function okReply() {
  step({ kind: 'buttons', text: T('ok_reply', V()), buttons: [B('ORDER', 'btn_order'), B('USAGE', 'btn_usage')] });
  log.push('[offered to order]');
}

// Answers go before the order step; when no order is going on, the last answer carries a 🛒 Order button
// (not twice in a row).
const orderOpen = orderingNow || (draft && draft.status === 'draft' && anyDetail(draft));
const lastBot = [...(ctx.history || [])].reverse().find(h => h.r === 'b');
const offeredLast = !!(lastBot && /\[offered to order|\[greeted them/.test(String(lastBot.c)));
if (answers.length) {
  const firstStep = blocks.findIndex(b => b.kind !== 'image' && !b.pid && b.kind !== 'note');
  const ans = answers.map(t => ({ kind: 'text', text: t }));
  if (!orderOpen && !stepAdded && event !== 'confirmed' && status0 !== 'ordered' && !notInterested && !offeredLast && intent !== 'spam') {
    const lastA = ans.pop();
    ans.push({ kind: 'buttons', text: lastA.text, buttons: [B('ORDER', 'btn_order')] });
    log.push('[offered to order]');
  }
  if (firstStep >= 0) blocks.splice(firstStep, 0, ...ans); else blocks.push(...ans);
}
const out = blocks.filter(b => b.kind !== 'note');

// ---------- status ----------
let status = status0;
if (intent === 'spam') status = 'spam';
else if (event === 'confirmed') status = 'ordered';
else if (event === 'cancelled') status = 'cancelled';
else if (notInterested) status = 'not_interested';
else if (orderingNow && (awaitingOut || (draft && draft.status === 'draft'))) status = 'ordering';
else if (status0 === 'ordered' || status0 === 'ordering') status = status0;
else if (saidSomething) status = 'asking';
if (status === 'ordering' && !saidSomething && !u.lead) status = status0 === 'new' ? 'new' : status;

function rule(name) { return u.rule === name; }

return [{ json: {
  blocks: out,
  route,
  lang,
  ai: u.need_ai ? { from: aiFrom || null, error: aiError || null } : null,
  save: {
    user_id: m.user_id, phone: m.phone, test: !!m.test,
    msgs: (ctx.msgs || []).map(x => ({ wa_id: x.wa_id, t: x.t, kind: x.kind })),
    log: log.join('\n'),
    route,
    chat: {
      product_id: pid || null, seen_add: seenAdd, lang, status, awaiting: awaitingOut || '',
      needs_call: needsCall, call_reason: callReason, pause, said_something: saidSomething,
      memo: aiFrom ? String(c.memo || '').slice(0, 300) : '', unsure, details: detailsOut,
    },
    order: draft && (draft.id || orderingNow || event) && draft.product_id ? {
      id: draft.id || null, product_id: draft.product_id, qty: draft.qty || 1, name: draft.name || null, address: draft.address || null,
      phone1: draft.phone1 || null, phone2: draft.phone2 || null, status: draft.status,
    } : null,
  },
} }];

// Reply blocks → WhatsApp Cloud API messages, in order. Texts next to each other become one message
// unless a block must stand alone (the photo text, the thank-you, how to use). Limits: reply buttons ≤3
// (titles ≤20), list rows ≤10 (titles ≤24, descriptions ≤72), body / caption ≤1024, text ≤4096.
// No blocks (spam, a plain "ok" while we wait for details) → one "skip" item, so the turn is still saved.
const m = $('Message').first().json;
const src = $input.first().json;
const to = String(m.phone);
const clip = (s, n) => Array.from(String(s || '')).slice(0, n).join('');
const len = s => Array.from(String(s || '')).length;
const url = `https://graph.facebook.com/${$('Config').first().json.GRAPH_VERSION}/${m.phone_number_id}/messages`;
const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to };

const out = [];
let pend = '', pendPid = null;
const push = (pid, body, text, kind, meta) => out.push({ json: { pid, text, kind, meta: meta || null, body, url } });
const flush = () => {
  if (!pend) return;
  push(pendPid, { ...base, type: 'text', text: { body: clip(pend, 4096), preview_url: false } }, clip(pend, 4096), 'text');
  pend = ''; pendPid = null;
};
const join = (a, b) => (a ? a + '\n\n' + b : b);

for (const b of src.blocks || []) {
  if (b.kind === 'text') {
    if (!b.text) continue;
    if (b.sep) { flush(); pend = b.text; pendPid = b.pid || null; flush(); continue; }
    if (len(join(pend, b.text)) > 4096) flush();
    pend = join(pend, b.text);
    if (b.pid) pendPid = b.pid;
  } else if (b.kind === 'image') {
    flush();
    push(b.pid, { ...base, type: 'image', image: { link: b.image, caption: clip(b.caption, 1024) } }, clip(b.caption, 1024), 'image', { image: b.image });
  } else if (b.kind === 'flow') {
    let text = join(pend, b.text);
    if (len(text) > 1024) { flush(); text = b.text; }
    const pid = pendPid; pend = ''; pendPid = null;
    push(pid, { ...base, type: 'interactive', interactive: { type: 'flow', body: { text: clip(text, 1024) }, action: { name: 'flow', parameters: {
      flow_message_version: b.version || '3', flow_token: b.token, flow_id: b.flow_id, flow_cta: clip(b.cta, 20),
      flow_action: 'navigate', flow_action_payload: { screen: 'ORDER', data: b.data } } } } },
      clip(text, 1024) + '\n[' + clip(b.cta, 20) + ']', 'buttons', { buttons: [clip(b.cta, 20)], form: true });
  } else if (b.kind === 'buttons' || b.kind === 'list') {
    let text = join(pend, b.text);
    if (len(text) > 1024) { flush(); text = b.text; }
    const pid = pendPid; pend = ''; pendPid = null;
    const action = b.kind === 'buttons'
      ? { buttons: b.buttons.slice(0, 3).map(x => ({ type: 'reply', reply: { id: x.id, title: clip(x.title, 20) } })) }
      : { button: clip(b.button, 20), sections: [{ title: clip(b.section || 'Choose', 24), rows: b.rows.slice(0, 10).map(r => ({
          id: r.id, title: clip(r.title, 24), ...(r.description ? { description: clip(r.description, 72) } : {}) })) }] };
    const labels = b.kind === 'buttons' ? action.buttons.map(x => x.reply.title) : action.sections[0].rows.map(x => x.title);
    push(pid, { ...base, type: 'interactive', interactive: { type: b.kind === 'buttons' ? 'button' : 'list', body: { text: clip(text, 1024) }, action } },
      clip(text, 1024), b.kind, b.kind === 'buttons' ? { buttons: labels } : { list: clip(b.button, 20), rows: labels });
  }
}
flush();
return out.length ? out : [{ json: { skip: true } }];

// What was sent (WhatsApp ids for delivery statuses and quoted replies) + every AI call's usage →
// the whole turn saved in one database call. In test mode nothing was sent.
const m = $('Message').first().json;
const plan = $('Plan Reply').first().json;
const outs = $('Split Outgoing').all().filter(o => !o.json.skip);
const results = m.test ? [] : $input.all();
const sent = [], productMsgs = [];
outs.forEach((o, i) => {
  const r = results[i] ? (results[i].json || {}) : {};
  const id = ((r.messages || [])[0] || {}).id || null;
  const e = r.error ? (typeof r.error === 'string' ? r.error : `${r.error.code || ''} ${r.error.message || ''}`.trim()) : null;
  sent.push({ wa_id: id, text: o.json.text, kind: o.json.kind, meta: o.json.meta, error: m.test ? null : (e || (id ? null : 'no message id')) });
  if (o.json.pid && id) productMsgs.push({ wa_id: id, product_id: o.json.pid });
});

const usage = [];
const u = $('Understand').first().json;
const b = u.brain || {};
const add = (node, provider, model) => {
  if (!$(node).isExecuted) return;
  const r = $(node).first().json || {};
  const use = r.usage || r.usageMetadata || null;
  usage.push({ task: 'brain', provider, model, usage: use, ok: !r.error && !!use, ms: b.started ? Date.now() - b.started : null,
               error: r.error ? String(r.error.message || JSON.stringify(r.error)).slice(0, 300) : null });
};
add('OpenAI: Brain', 'openai', b.openai_model);
add('Gemini: Brain', 'gemini', b.gemini_model);

return [{ json: { p: { ...plan.save, sent, product_msgs: productMsgs, usage } } }];

// "Try Lingo" in the panel: what the customer would have received, how it was understood and what
// the AI cost: the same pipeline as a real WhatsApp message.
const m = $('Message').first().json;
const gate = $('Gate').isExecuted ? $('Gate').first().json : {};
if (!$('Save Turn').isExecuted) {
  const claim = $('Claim Batch').isExecuted ? $('Claim Batch').first().json : {};
  return [{ json: { reply: { ok: true, stopped: gate.status !== 'ok' ? gate.status : (claim.why || 'stopped'), messages: [] } } }];
}
const st = $('Build Save Turn').first().json.p;
const saved = $('Save Turn').first().json || {};
const u = $('Understand').first().json;
const plan = $('Plan Reply').first().json;
return [{ json: { reply: {
  ok: true,
  phone: m.phone,
  route: st.route,
  status: st.chat.status,
  needs_call: st.chat.needs_call,
  call_reason: st.chat.call_reason || null,
  lang: st.chat.lang,
  understood: { intent: (plan.ai && plan.ai.from) ? 'ai' : (u.rule || u.source), ai: plan.ai, product_id: st.chat.product_id },
  log: st.log,
  messages: $('Split Outgoing').all().filter(o => !o.json.skip).map(o => ({ kind: o.json.kind, text: o.json.text, body: o.json.body, pid: o.json.pid || null })),
  ai: (st.usage || []).map(x => ({ task: x.task, model: x.model, ok: x.ok, in: ((x.usage || {}).prompt_tokens || (x.usage || {}).promptTokenCount || 0),
    cached: (((x.usage || {}).prompt_tokens_details || {}).cached_tokens || 0), out: ((x.usage || {}).completion_tokens || ((x.usage || {}).candidatesTokenCount || 0) + ((x.usage || {}).thoughtsTokenCount || 0)) })),
  ad_match: $('AI: Ad Match').isExecuted,
  cost_usd: Number(saved.cost_usd || 0),
  order_id: saved.order_id || null,
} } }];
